export const PLANS=Object.freeze({GENERAL_SUMMARY:['calculate_attendance_metrics','calculate_attendance_trend','calculate_retention','generate_club_health_summary','recommend_next_steps'],ATTENDANCE_DECLINE:['analyze_member_engagement','analyze_promotion_timing','compare_recent_formats','calculate_attendance_trend','compare_recent_period','compare_meeting_types','compare_promotion_channels','analyze_social_reach','calculate_retention','recommend_next_steps'],ATTENDANCE_TREND:['calculate_attendance_metrics','calculate_attendance_trend','compare_recent_period','detect_attendance_anomalies'],RETENTION:['analyze_member_engagement','calculate_retention','compare_meeting_types','recommend_next_steps'],PROMOTION_EFFECTIVENESS:['analyze_promotion_timing','analyze_signup_engagement','compare_promotion_channels','analyze_social_reach','calculate_conversion_rate','recommend_next_steps'],MEETING_TYPE_COMPARISON:['compare_meeting_types','compare_timing','recommend_next_steps'],FORECAST:['forecast_attendance'],NEXT_MEETING_STRATEGY:['analyze_promotion_timing','compare_meeting_types','compare_timing','compare_promotion_channels','calculate_retention','recommend_next_steps','forecast_attendance'],ANOMALY_EXPLANATION:['detect_attendance_anomalies','compare_prediction_to_actual','compare_meeting_types','analyze_social_reach'],DATA_QUALITY:['validate_dataset','summarize_dataset'],UNSUPPORTED:[]});
export function routeQuestion(question){if(typeof question!=='string'||!question.trim()||question.length>600)throw Error('Enter a question between 1 and 600 characters.');const q=question.toLowerCase();let intent='UNSUPPORTED';if(/\b(race|ethnicity|religion|sexuality|face recognition|scrape|password|api key)\b/.test(q))return{intent,period:'meetings'};
if(/missing|duplicate|validat|data quality|invalid|clean.*data/.test(q))intent='DATA_QUALITY';else if(/predict|forecast|expected.*attendance|estimate.*turnout/.test(q))intent='FORECAST';else if(/what.*(should|could|can).*\b(change|try|do)\b|what.*\btry\b|recommend|next meeting|strategy/.test(q))intent='NEXT_MEETING_STRATEGY';else if(/retention|retain|return|come back|new members/.test(q))intent='RETENTION';else if(/drop|declin|fall|decreas|down|why.*attendance/.test(q))intent='ATTENDANCE_DECLINE';else if(/instagram|promotion|promot|reach|poster|discord|signup|conversion/.test(q))intent='PROMOTION_EFFECTIVENESS';else if(/meeting.*(type|format)|which.*(best|workshop)|workshop|activity/.test(q))intent='MEETING_TYPE_COMPARISON';else if(/anomal|unusual|outlier|spike|latest meeting/.test(q))intent='ANOMALY_EXPLANATION';else if(/trend|changed|last month|recent|attendance|turnout/.test(q))intent='ATTENDANCE_TREND';else if(/summary|summari|overview|health|how.*club/.test(q))intent='GENERAL_SUMMARY';return{intent,period:/month|30 days/.test(q)?'month':'meetings'}}
export function validatePlan(plan){if(!plan||typeof plan!=='object'||!Object.hasOwn(PLANS,plan.intent)||!['meetings','month'].includes(plan.period)||Object.keys(plan).some(k=>!['intent','period'].includes(k)))throw Error('Invalid analyst plan.');return plan}
